 std::ofstream out(root/"expected.bin",std::ios::binary);auto bytes=payload(population,algorithm,random);out.write(bytes.data(),bytes.size());out.close();if(!out)throw std::runtime_error("expected state write failure");std::cout<<genetikVersion<<" producer full state saved\n";
